package com.networkmonitorpro.ui; import android.content.*;import android.net.*;import android.os.*;import android.view.*;import android.widget.*;import androidx.fragment.app.*;import androidx.lifecycle.*;import androidx.recyclerview.widget.*;import com.networkmonitorpro.R;import com.networkmonitorpro.data.entity.DownloadHistory;import com.networkmonitorpro.service.DownloadService;import com.networkmonitorpro.ui.adapter.DownloadAdapter;import com.networkmonitorpro.ui.viewmodel.MainViewModel; public class DownloaderFragment extends Fragment{ public View onCreateView(LayoutInflater i,ViewGroup c,Bundle b){return i.inflate(R.layout.fragment_downloader,c,false);} public void onViewCreated(View v,Bundle b){MainViewModel m=new ViewModelProvider(requireActivity()).get(MainViewModel.class); EditText url=v.findViewById(R.id.urlInput); CheckBox over=v.findViewById(R.id.override5g); DownloadAdapter a=new DownloadAdapter(new DownloadAdapter.Listener(){public void pause(DownloadHistory d){toast("Paused "+d.fileName);} public void resume(DownloadHistory d){toast("Resumed "+d.fileName);} public void cancel(DownloadHistory d){toast("Cancelled "+d.fileName);}}); RecyclerView rv=v.findViewById(R.id.downloadList);rv.setLayoutManager(new LinearLayoutManager(requireContext()));rv.setAdapter(a);m.downloads.all().observe(getViewLifecycleOwner(),a::submit); v.findViewById(R.id.addDownload).setOnClickListener(x->{String u=url.getText().toString().trim(); if(!URLUtil.isNetworkUrl(u)){url.setError("Enter a valid URL");return;} String name=Uri.parse(u).getLastPathSegment(); if(name==null||name.isEmpty())name="download.bin"; m.downloads.add(new DownloadHistory(u,name,"General","Queued",requireContext().getExternalFilesDir(null)+"/"+name,0,0,0,0,System.currentTimeMillis(),!over.isChecked())); Intent in=new Intent(requireContext(), DownloadService.class).setAction(DownloadService.ACTION_ADD).putExtra(DownloadService.EXTRA_URL,u).putExtra(DownloadService.EXTRA_OVERRIDE,over.isChecked()); if(Build.VERSION.SDK_INT>=26)requireContext().startForegroundService(in); else requireContext().startService(in);});} private void toast(String s){Toast.makeText(requireContext(),s,Toast.LENGTH_SHORT).show();} }
